='blocked', +                                                      reason=str(error))) +                with locked(self.root / 'accounts/router.lock'): +                    live, interactive = router.occupancy(self.root) +                    caps, total, mode = router.admission_limits(self.root, interactive) +                    report['census'] = dict(workers_and_reservations=live, interactive=interactive, +                                            caps=caps, total=total, mode=mode, recovery_ceiling=10, +                                            tickets=router.queue_tickets(self.root)) +                    _, clients = router.host_processes() +                    report['census']['observed_clients_including_exempt'] = { +                        pid: dict(account=account, interactive=is_interactive) +                        for pid, (account, is_interactive) in clients.items()} +                if (self.directory / 'HOLD').exists() or (self.directory / 'STOP').exists(): +                    report['status'] = 'stopped' +                elif report['status'] == 'idle' and report['packets']: +                    statuses = {row['status'] for row in report['packets']} +                    if 'blocked' in statuses or 'held' in statuses: report['status'] = 'blocked' +                    elif statuses & {'running', 'launching'}: report['status'] = 'active' +                if report['status'] == 'idle': +                    report['reason'] = 'No unattempted useful packets; main must select more work.' +                report['evidence'] = state['evidence'] +            except (OSError, ValueError, KeyError, TypeError, LayerError, +                    subprocess.SubprocessError) as error: +                self.hold(str(error)) +                report.update(status='held', reason=str(error)) +            if state is not None: save(self.state_path, state) +            save(self.directory / 'census.json', report) +            self.event('census', report=report) +            return report +def child_environment(root: Path) -> dict: +    \"\"\"Do not inherit routing, prompt-ref, resume, model, or automatic-fix overrides.\"\"\" +    environment = {key: value for key, value in os.environ.items() +                   if key == 'MIPSTARRE_LAKE_ROOT' or +                   (not key.startswith('MIPSTARRE_') and key != 'CODEX_HOME')} +    environment.update(MIPSTARRE_CACHE_ROOT=str(root), MIPSTARRE_CODEX_ACCOUNT='primary', +                       MIPSTARRE_CODEX_MODEL='gpt-6-astra', MIPSTARRE_REVIEW_MODEL='gpt-6-astra', +                       MIPSTARRE_PROSE_MODEL='gpt-6-astra', MIPSTARRE_ACCOUNT_WAIT='0', +                       MIPSTARRE_REVIEW_LOCK_WAIT='0', MIPSTARRE_DISPATCH_LOCK_WAIT='0', +                       MIPSTARRE_SESSION=os.environ.get('MIPSTARRE_SESSION', 'main-useful-queue'), +                       LOCAL_AUTO_FIX_ENABLED='false') +    return environment +def execute(primary: Path, root: Path, identifier: str) -> int: +    \"\"\"Run a frozen intent once; only a matching live reservation authorizes execution.\"\"\" +    supervisor = Supervisor(primary, root) +    launch_dir = supervisor.directory / identifier +    with locked(supervisor.directory / 'controller.lock'): +        launch = load(launch_dir / 'launch.json') +        with locked(root / 'accounts/router.lock'): +            ticket = router.queue_tickets(root).get(launch['token']) +            if (not ticket or ticket['pid'] != os.getpid() or +                    ticket['start'] != router.process_identity(os.getpid()) or +                    (launch_dir / 'receipt.json').exists()): +                raise ValueError('execution has no matching live one-shot intent') +    packet = launch['packet'] +    receipt = dict(token=launch['token'], ok=False, ts=utcnow()) +    try: +        if (supervisor.directory / 'STOP').exists() or (supervisor.directory / 'HOLD').exists(): +            raise ValueError('stopped before launch') +        task = packet_gate(packet, primary, ro