tatuses. CI uses the normal 14400-second lock wait. +Main owns the second independent normal review and terminal disposition after +green CI. This session starts no model review, subagent, merge daemon, deployment, +or provider probe and does not reset time, review, or source-line budgets. diff --git a/scripts/tests/test_dispatch.py b/scripts/tests/test_dispatch.py index 31e501a..8a075ed 100644 --- a/scripts/tests/test_dispatch.py +++ b/scripts/tests/test_dispatch.py @@ -390,9 +390,12 @@ class DispatchCommandTests(unittest.TestCase):              subprocess.run([\"git\", \"init\", \"-q\", \"-b\", \"main\"], cwd=worktree, check=True)              target.mkdir(parents=True)              (worktree / \".lake\").symlink_to(target, target_is_directory=True) +            alias = root / 'alias' +            alias.symlink_to(worktree, target_is_directory=True)              with mock.patch.dict(os.environ, {\"MIPSTARRE_LAKE_ROOT\": str(target.parent)}): -                argv = self.dispatch_command(\"--role\", \"prover\", \"--worktree\", str(worktree), +                argv = self.dispatch_command(\"--role\", \"prover\", \"--worktree\", str(alias),                                               \"--sandbox\", \"workspace-write\") +        self.assertEqual(argv[argv.index('-C') + 1], str(worktree))          self.assertEqual(argv[argv.index(\"--add-dir\") + 1], str(target.resolve()))          self.assertLess(argv.index(\"--add-dir\"), argv.index(\"-o\"))   diff --git a/scripts/tests/test_github_workflow.py b/scripts/tests/test_github_workflow.py index 6ad2b13..744c614 100644 --- a/scripts/tests/test_github_workflow.py +++ b/scripts/tests/test_github_workflow.py @@ -473,6 +473,35 @@ class ReviewRoundCounterTests(LayerTestCase):          self.assertNotIn(\"DUPLICATE-PUBLICATION\", prior)     +    def test_queue_refuses_fifth_round_and_existing_head_publication(self) -> None: +        for label, reviews, statuses, expected in ( +            ('cap', [self._review(str(number) * 40, 'prior') for number in range(1, 5)], +             [], 'four-round cap'), +            ('partial', [self._review(self.head, 'already published')], [], +             'publication evidence'), +            ('summary', [], [{'context': 'local-review/summary', 'state': 'pending'}], +             'summary evidence'), +        ): +            with self.subTest(label=label): +                self.gh.reset() +                self.gh.route(r'^pulls/7$', { +                    'number': 7, 'state': 'open', 'head': {'sha': self.head, 'ref': self.BRANCH}, +                    'base': {'ref': 'main'}, +                }) +                self.gh.route(r'^commits/[0-9a-f]+/statuses', statuses + [ +                    {'context': 'local-ci/summary', 'state': 'success'}]) +                self.gh.route(r'^pulls/7/reviews', reviews) +                environment = dict(os.environ, **self.gh.env(), +                    MIPSTARRE_CACHE_ROOT=str(self.tmp / f'queue-{label}'), +                    MIPSTARRE_QUEUE_TICKET='test-only', MIPSTARRE_QUEUE_EXPECTED_HEAD=self.head, +                    LOCAL_REVIEW_ENABLED='true', PYTHONDONTWRITEBYTECODE='1') +                result = subprocess.run(['bash', str(self.repo / 'local/bin/review.sh'), +                    '7', '--dry-run'], cwd=self.repo, capture_output=True, text=True, +                    env=environment) +                self.assertNotEqual(result.returncode, 0, result.stdout) +                self.assertIn(expected, result.stderr) + +  class MergeGateTests(LayerTestCase):      \"\"\"``pr_merge.py --check-only`` must refuse on thin evidence and pass on full.   diff --git a/scripts/tests/test_useful_queue.py b/scripts/tests/test_useful_queue.py new file mode 100644 index 0000000..a8262e4 --- /dev/null +++ b/scripts/tests/test_useful_queue.py @@ -0,0 +1,294 @@ +#!/usr/bin/env python3 +\"\"\"Queue regressions: preserved scenarios consolidated into fake-process/API fixtures.\"\"\" +import hashlib +from contextlib import ExitStack +import json +import os +from pathlib import Path +import sys +import tempfile +import unittest +from unittest import mock +REPO_ROOT = Path(__file__).resolve().parents[2] +sys.path.insert(0, str(REPO_ROOT / 'local/bin')) +import useful_queue as queue +HEAD, PARENT = 'a' * 40, 'b' * 40 + +class QueueTests(unittest.TestCase): +    def patch(self, target, name, **kwargs): +        return self.stack.enter_context(mock.patch.object(target, name, **kwargs)) +    def setUp(self): +        self.stack = ExitStack() +        self.addCleanup(self.stack.close) +        temporary = tempfile.TemporaryDirectory() +        self.addCleanup(temporary.cleanup) +        self.base = Path(temporary.name) +        self.primary, self.worktree = self.base / 'repo', self.base / 'worktree' +        self.worktree.mkdir() +        self.task = self.base / 'task.md' +        self.task.write_text('Prove the explicitly selected lemma.\\n') +        self.packet = dict(id='proof-257', kind='dispatch', issue=257, +            worktree=str(self.worktree), head=HEAD, parents=[], effort='xhigh', role='prover', +            task_file=str(self.task), task_sha256=hashlib.sha256(self.task.read_bytes()).hexdigest()) +        self.host = self.patch(queue.router, 'host_processes', return_value=({}, {})) +        self.identity = self.patch(queue.router, 'process_identity', return_value='123') +        self.stack.enter_context(mock.patch.dict(os.environ, {}, clear=True)) +        self.reset() +    def reset(self, name='cache'): +        self.root = self.base / name +        self.supervisor = queue.Supervisor(self.primary, self.root) +        self.directory = self.supervisor.directory +        self.config() +    def config(self, packets=None, enabled=True): +        queue.save(self.directory / 'queue.json', dict(version=1, enabled=enabled, +                   packets=[self.packet] if packets is None else packets)) +    def review(self): +        return {key: value for key, value in dict(self.packet, kind='review', pr=258).items() +                if key not in ('role', 'task_file', 'task_sha256')} +    def tick(self, status=None, calls=0, run=True, error=None): +        with mock.patch.object(queue, 'packet_gate', return_value=self.task.read_text()), \\ +             mock.patch.object(queue, 'worktree_busy', return_value=False), \\ +             mock.patch.object(queue.subprocess, 'Popen', side_effect=error) as popen: +            popen.return_value.pid = 1000 +            result = self.supervisor.tick(run) +        self.assertEqual(popen.call_count, calls) +        if calls: self.launch_environment = popen.call_args.kwargs['env'] +        if status is not None: self.assertEqual(result['status'], status, result) +        return result +    def tickets(self): return queue.router.queue_tickets(self.root) +    def api(self): +        defaults = dict(issue_view={'state': 'open'}, api=[], pr_reviews=[], +            pr_view={'state': 'open', 'head': {'sha': HEAD, 'ref': 'issue-257-proof'}}, +            latest_statuses={'local-ci/summary': {'state': 'success'}}) +        return {name: self.patch(queue.gh_common, name, return_value=value) +                for name, value in defaults.items()} +    def fake_git(self, worktree, *args): +        if args == ('rev-parse', 'HEAD'): return HEAD +        if '--git-common-dir' in args: return str(self.primary / '.git') +        return 'issue-257-proof' if args[0] == 'symbolic-ref' else '' +    def test_opt_in_empty_queue_and_capacity(self): +        for enabled, run in ((False, False), (False, True), (True, False)): +            self.config(enabled=enabled) +            self.tick('disabled', run=run) +        self.config([]) +        self.tick('idle') +        for name, live, interactive, settings, review, calls, cap in ( +            ('review-full', 9, 1, {}, True, 0, 11), ('review-room', 8, 1, {}, True, 1, 11), +            ('external', 3, 4, {'max-codex-primary': 4, 'primary-external-reserved': 5}, +             False, 0, 3), ): +            with self.subTest(name=name): +                self.reset(name) +                self.config([self.review() if review else self.packet]) +                for key, value in settings.items(): +                    queue.atomic_write(self.root / 'watchdog' / key, str(value)) +                with mock.patch.object(queue.router, 'occupancy', +                                       return_value=([live, 0], [interactive, 0])): +                    result = self.tick(calls=calls) +                self.assertEqual(result['census']['caps'][0], cap) +                if calls: self.assertEqual(next(iter(self.tickets().values()))['slots'], 2) +                else: +                    self.assertIn('capacity', result['packets'][0]['reason']) +        self.reset('enabled') +        result = self.tick('admitted', calls=1) +        self.assertEqual(result['census']['workers_and_reservations'], [1, 0]) +        self.assertIn('not server admission', result['limitation']) +    def test_terminal_and_uncertain_lifecycle_preserves_attempts(self): +        for scenario in ('stop', 'rename', 'missing', 'success', 'partial', 'restart', 'uncertain'): +            with self.subTest(scenario=scenario): +                self.reset(scenario) +                self.tick(calls=1, error=OSError('uncertain') if scenario == 'uncertain' else None) +                token = next(iter(self.tickets())) +                if scenario == 'stop': +                    (self.directory / 'STOP').touch() +                    self.config([self.packet, dict(self.packet, id='other', issue=999)]) +                if scenario == 'rename': self.config([dict(self.packet, id='renamed')]) +                if scenario in ('success', 'partial'): +                    queue.save(self.directory / self.packet['id'] / 'receipt.json', +                               dict(ok=scenario == 'success', token=token)) +                if scenario == 'restart': +                    self.supervisor = queue.Supervisor(self.primary, self.root) +                with mock.patch.object(queue.router, 'process_identity', +                        side_effect=ProcessLookupError if scenario == 'missing' else None, +                        return_value='123'), mock.patch.object(queue.os, 'kill') as kill: +                    result = self.tick() +                kill.assert_not_called() +                self.assertEqual(bool(self.tickets()), scenario != 'success') +                expected = {'restart': 'active', 'success': 'idle', 'rename': 'held'} +                self.assertEqual(result['status'], expected.get(scenario, 'stopped')) +                if scenario == 'success': self.assertEqual(result['packets'][0]['status'], 'done') +    def test_corrupt_state_unobservable_host_and_single_admission(self): +        (self.directory / 'state.json').write_text('{broken') +        self.tick('held') +        self.assertEqual((self.directory / 'state.json').read_text(), '{broken') +        self.reset('host') +        with mock.patch.object(queue.router, 'host_processes', side_effect=PermissionError): +            self.tick('held') +        self.reset('single') +        self.config([self.packet, dict(self.packet, id='second-packet', issue=999)]) +        self.assertEqual(self.tick(calls=1)['packets'][1]['status'], 'queued') +    def test_ticket_accounting_identity_and_duplicate_worktree(self): +        (self.root / 'accounts').mkdir() +        ticket = dict(slots=2, pid=1000, start='123', claims=[], worktree=str(self.worktree)) +        queue.router.write_queue_tickets(self.root, {'token': ticket}) +        self.assertEqual(queue.router.occupancy(self.root), ([2, 0], [1, 0])) +        self.assertTrue(queue.worktree_busy(self.packet, self.root)) +        queue.atomic_write(self.root / 'watchdog/max-codex-primary', '2') +        with self.assertRaisesRegex(ValueError, 'capacity'): +            queue.router.reserve(self.root, 'primary', 1001, 0, True) +        self.host.return_value = ({1001: 1000}, {}) +        (self.root / 'watchdog/max-codex-primary').unlink() +        alias = self.base / 'alias' +        alias.symlink_to(self.worktree, target_is_directory=True) +        self.stack.enter_context(mock.patch.dict(os.environ, { +            'MIPSTARRE_DISPATCH_WORKTREE': str(alias)})) +        with self.assertRaisesRegex(ValueError, 'worktree reserved'): +            queue.router.reserve(self.root, 'primary', 1001, 0, True) +        os.environ['MIPSTARRE_QUEUE_TICKET'] = 'token' +        self.patch(queue.router.os, 'kill') +        self.assertEqual(queue.router.reserve(self.root, 'primary', 1001, 0, False), 'primary') +        self.assertEqual(queue.router.occupancy(self.root)[0], [2, 0]) +        with self.assertRaisesRegex(ValueError, 'unused descendant'): +            queue.router.reserve(self.root, 'primary', 1001, 0, False) +        for token, account, parent, identity in ( +            ('missing', 'primary', 1000, '123'), ('token', 'second', 1000, '123'), +            ('token', 'primary', 2000, '123'), ('token', 'primary', 1000, '456')): +            os.environ['MIPSTARRE_QUEUE_TICKET'] = token +            self.host.return_value, self.identity.return_value = ({1002: parent}, {}), identity +            with self.assertRaises(ValueError): +                queue.router.reserve(self.root, account, 1002, 0, False) +        (self.directory / 'STOP').touch() +        with self.assertRaisesRegex(ValueError, 'stopped'): +            queue.router.reserve(self.root, 'primary', 1002, 0, False) +        queue.router.write_queue_tickets(self.root, {}) +        (self.root / 'locks/review-258.lock').mkdir(parents=True) +        self.assertTrue(queue.worktree_busy(self.review(), self.root)) +    def test_observed_refusals_progress_and_partial_logs(self): +        self.tick(calls=1) +        path = self.directory / self.packet['id'] / 'launch.log' +        clean = ['wall_s: 503', 'tokens_total: 150295', 'name: scout-429-retry', +                 'worktree: /tmp/concurrency-503', '> ERROR: 429 retry', +                 'Incident: ERROR: concurrency limit exceeded', +                 json.dumps({'type': 'item.completed', 'error': 'quoted 503 retry', +                             'item': {'output': 'ERROR: concurrency limit exceeded'}})] +        path.write_text('\\n'.join(clean) + '\\n') +        evidence = self.tick('active')['evidence'][str(path)] +        self.assertEqual((evidence['retries'], evidence['refusals']), (0, 0)) +        events = [{'type': 'turn.completed'}, {'type': 'item.completed'}, +                  {'type': 'error', 'message': 'Reconnecting: concurrency limit exceeded'}] +        with path.open('a') as handle: +            handle.write('\\n'.join(map(json.dumps, events)) + '\\n') +        result = self.tick('stopped') +        self.assertEqual([result['evidence'][str(path)][key] +                          for key in ('turns', 'items', 'retries', 'refusals')], [1, 2, 1, 1]) +        self.assertEqual(self.tick()['evidence'][str(path)]['turns'], 1) +        (self.directory / 'HOLD').unlink() +        self.tick('active') +        path = self.base / 'partial' +        path.write_text('{\"type\":\"turn.completed\"') +        cursor = queue.observe(path, {}) +        self.assertEqual(cursor['offset'], 0) +        path.write_text('{\"type\":\"turn.completed\"}\\n' + json.dumps({ +            'type': 'item.completed', 'item': {'output': 'test concurrency refusal'}}) + '\\n') +        cursor = queue.observe(path, cursor) +        self.assertEqual((cursor['turns'], cursor['refusals']), (1, 0)) +        path.write_text('') +        with self.assertRaisesRegex(ValueError, 'truncated'): queue.observe(path, cursor) +        path.write_text('ERROR: unexpected status 503\\nReconnecting 1/5: retry after 429\\n' + +                        json.dumps({'type': 'turn.failed', 'error': {'message': 'quota'}}) + '\\n') +        evidence = queue.observe(path, {}) +        self.assertEqual((evidence['retries'], evidence['refusals']), (1, 3)) +    def test_schema_environment_and_canonical_handoff_guards(self): +        for field, value in (('command', 'touch /tmp/injection'), ('resume', 'thread'), +                             ('effort', 'low'), ('role', 'orc'), ('kind', 'merge')): +            self.config([dict(self.packet, **{field: value})]) +            with self.subTest(field=field), self.assertRaises(ValueError): +                queue.configuration(self.directory / 'queue.json') +        with mock.patch.dict(os.environ, {'CODEX_HOME': '/second', +                'MIPSTARRE_CODEX_ACCOUNT': 'second', 'MIPSTARRE_PERSONA_REF': 'evil', +                'MIPSTARRE_REVIEW_EFFORT': 'low', 'LOCAL_REVIEW_ENABLED': 'false'}): +            environment = queue.child_environment(self.root) +        self.assertFalse({'CODEX_HOME', 'MIPSTARRE_PERSONA_REF'} & environment.keys()) +        self.assertEqual([environment[key] for key in ('MIPSTARRE_CODEX_ACCOUNT', +            'MIPSTARRE_CODEX_MODEL', 'MIPSTARRE_ACCOUNT_WAIT', 'LOCAL_REVIEW_ENABLED')], +            ['primary', 'gpt-6-astra', '0', 'false']) +    def test_parent_merge_binding_task_integrity_and_dirty_worktree(self): +        api = self.api() +        self.patch(queue, 'git', side_effect=self.fake_git) +        api['api'].return_value = [{'number': 256, 'state': 'closed'}] +        with self.assertRaisesRegex(ValueError, 'parent bindings'): +            queue.packet_gate(self.packet, self.primary, self.root) +        self.packet['parents'] = [dict(issue=256, pr=255, merge_sha=PARENT)] +        api['pr_view'].return_value = dict(merged=False, merge_commit_sha=PARENT) +        with self.assertRaisesRegex(ValueError, 'not confirmed'): +            queue.packet_gate(self.packet, self.primary, self.root) +        api['pr_view'].return_value['merged'] = True +        api['issue_view'].side_effect = lambda number: { +            'state': 'open' if number == 257 else 'closed'} +        self.assertEqual(queue.packet_gate(self.packet, self.primary, self.root), +                        