te.get('version') != 1 or +                        not isinstance(state.get('packets'), dict) or +                        not isinstance(state.get('evidence'), dict)): +                    raise ValueError('invalid queue state; adoption required') +                self.refresh(state) +                config = configuration(self.directory / 'queue.json') +                enabled = run and config['enabled'] +                if not enabled: report['status'] = 'disabled' +                for packet in config['packets']: +                    prior = state['packets'].get(packet['id']) +                    if prior: +                        if prior['fingerprint'] != fingerprint(packet): +                            raise ValueError('attempted packet changed; adoption required') +                        report['packets'].append(dict(id=packet['id'], status=prior['status'])) +                        continue +                    if any(entry['fingerprint'] == fingerprint(packet) +                           for entry in state['packets'].values()): +                        raise ValueError('duplicate task under a new id; adoption required') +                    if not enabled: +                        report['packets'].append(dict(id=packet['id'], status='not-enabled')) +                        continue +                    if report['status'] == 'admitted': +                        report['packets'].append(dict(id=packet['id'], status='queued')) +                        continue +                    if (self.directory / 'STOP').exists() or (self.directory / 'HOLD').exists(): +                        report['status'] = 'stopped' +                        break +                    try: +                        task = packet_gate(packet, self.primary, self.root) +                        with locked(self.root / 'accounts/router.lock'): +                            live, interactive = router.occupancy(self.root) +                            caps, total, mode = router.admission_limits(self.root, interactive) +                            slots = 2 if packet['kind'] == 'review' else 1 +                            if (mode != 'primary' or live[0] + slots > min(10, caps[0]) or +                                    sum(live) + slots > total): +                                raise ValueError('capacity: primary recovery ceiling 10 ' +                                                 'or owner limit') +                            if worktree_busy(packet, self.root): +                                raise ValueError('worktree already occupied or reserved') +                            if any((self.directory / name).exists() for name in ('STOP', 'HOLD')): +                                raise ValueError('stop/hold appeared before reservation') +                            self.launch(packet, task, state) +                        report['status'] = 'admitted' +                        report['packets'].append(dict(id=packet['id'], status='running')) +                    except (OSError, ValueError, LayerError, subprocess.SubprocessError) as error: +                        if packet['id'] in state['packets']: +                            state['packets'][packet['id']]['status'] = 'held' +                            self.hold(f\"{packet['id']}: {error}\") +                        report['packets'].append(dict(id=packet['id'], status='blocked', +                                                      reason=str(error))) +                with locked(self.root / 'accounts/router.lock'): +                    live, interactive = router.occupancy(self.root) +                    caps, total, mode = router.admission_limits(self.root, interactive) +                    report['census'] = dict(workers_and_reservations=live, interactive=interactive, +                                            caps=caps, total=total, mode=mode, recovery_ceiling=10, +                                            tickets=router.queue_tickets(self.root)) +                    _, clients = router.host_processes() +                    report['census']['observed_clients_including_exempt'] = { +                        pid: dict(account=account, interactive=is_interactive) +                        for pid, (account, is_interactive) in clients.items()} +                if (self.directory / 'HOLD').exists() or (self.directory / 'STOP').exists(): +                    report['status'] = 'stopped' +                elif report['status'] == 'idle' and report['packets']: +                    statuses = {row['status'] for row in report['packets']} +                    if 'blocked' in statuses or 'held' in statuses: report['status'] = 'blocked' +                    elif statuses & {'running', 'launching'}: report['status'] = 'active' +                if report['status'] == 'idle': +                    report['reason'] = 'No unattempted useful packets; main must select more work.' +                report['evidence'] = state['evidence'] +            except (OSError, ValueError, KeyError, TypeError, LayerError, +                    subprocess.SubprocessError) as error: +                self.hold(str(error)) +                report.update(status='held', reason=str(error)) +            if state is not None: save(self.state_path, state) +            save(self.directory / 'census.json', report) +            self.event('census', report=report) +            return report +def child_environment(root: Path) -> dict: +    \"\"\"Do not inherit routing, prompt-ref, resume, model, or automatic-fix overrides.\"\"\" +    environment = {key: value for key, value in os.environ.items() +                   if key == 'MIPSTARRE_LAKE_ROOT' or +                   (not key.startswith('MIPSTARRE_') and key != 'CODEX_HOME')} +    environment.update(MIPSTARRE_CACHE_ROOT=str(root), MIPSTARRE_CODEX_ACCOUNT='primary', +                       MIPSTARRE_CODEX_MODEL='gpt-6-astra', MIPSTARRE_REVIEW_MODEL='gpt-6-astra', +                       MIPSTARRE_PROSE_MODEL='gpt-6-astra', MIPSTARRE_ACCOUNT_WAIT