issue', str(packet['issue']), +                       '--worktree', packet['worktree'], '--effort', packet['effort'], '--', +                       task + '\\nComplete this one-shot packet without dispatching other sessions. ' +                       'Do not merge, resume proof budgets, or dispose of owner inbox items.'] +        result = subprocess.run(command, env=environment, stdin=subprocess.DEVNULL) +        receipt['exit'] = result.returncode +        if receipt['exit'] != 0: +            raise ValueError('canonical tool failed; preserve launch evidence for adoption') +        if packet['kind'] == 'review': +            review_evidence(packet, finished=True) +            review_dir = root / f\"reviews/pr{packet['pr']}\" / packet['head'] +            for path in review_dir.glob('*.rc'): +                if path.read_text().strip() != '0': +                    raise ValueError('review lane failed; adopt partial publication') +        else: +            log = (launch_dir / 'launch.log').read_text(errors='replace') +            names = re.findall(r'^name: ([a-z0-9-]+)$', log, re.M) +            rows = router.session_rows(primary / 'results/telemetry/sessions.jsonl') +            rows = [row for row in rows if names and row.get('name') == names[-1]] +            if not rows or not rows[-1].get('thread_id') or rows[-1].get('exit') != 0: +                raise ValueError('dispatch telemetry incomplete; adoption required') +            name = names[-1] +            published = primary / 'results/telemetry/sessions' +            if any(not (published / f'{name}{suffix}').is_file() or +                   not (published / f'{name}{suffix}').stat().st_size +                   for suffix in ('.jsonl', '.last.md')): +                raise ValueError('dispatch capture publication incomplete; adoption required') +            receipt['session'] = name +        receipt['ok'] = True +    except (OSError, ValueError, KeyError, LayerError, subprocess.SubprocessError) as error: +  