 status is not None: self.assertEqual(result['status'], status, result) +        return result +    def tickets(self): return queue.router.queue_tickets(self.root) +    def api(self): +        defaults = dict(issue_view={'state': 'open'}, api=[], pr_reviews=[], +            pr_view={'state': 'open', 'head': {'sha': HEAD, 'ref': 'issue-257-proof'}}, +            latest_statuses={'local-ci/summary': {'state': 'success'}}) +        return {name: self.patch(queue.gh_common, name, return_value=value) +                for name, value in defaults.items()} +    def fake_git(self, worktree, *args): +        if args == ('rev-parse', 'HEAD'): return HEAD +        if '--git-common-dir' in args: return str(self.primary / '.git') +        return 'issue-257-proof' if args[0] == 'symbolic-ref' else '' +    def test_opt_in_empty_queue_and_capacity(self): +        for enabled, run in ((False, False), (False, True), (True, False)): +            self.config(enabled=enabled) +            self.tick('disabled', run=run) +        self.config([]) +        self.tick('idle') +        for name, live, interactive, settings, review, calls, cap in ( +            ('review-full', 9, 1, {}, True, 0, 11), ('review-room', 8, 1, {}, True, 1, 11), +            ('external', 3, 4, {'max-codex-primary': 4, 'primary-external-reserved': 5}, +             False, 0, 3), ): +            with self.subTest(name=name): +                self.reset(name) +                self.config([self.review() if review else self.packet]) +                for key, value in settings.items(): +                    queue.atomic_write(self.root / 'watchdog' / key, str(value)) +                with mock.patch.object(queue.router, 'occupancy', +                                       return_value=([live, 0], [interactive, 0])): +                    result = self.tick(calls=calls) +                self.assertEqual(result['census']['caps'][0], cap) +                if calls: self.assertEqual(next(iter(self.tickets().values()))['slots'], 2