': self.assertEqual(result['packets'][0]['status'], 'done') +    def test_corrupt_state_unobservable_host_and_single_admission(self): +        (self.directory / 'state.json').write_text('{broken') +        self.tick('held') +        self.assertEqual((self.directory / 'state.json').read_text(), '{broken') +        self.reset('host') +        with mock.patch.object(queue.router, 'host_processes', side_effect=PermissionError): +            self.tick('held') +        self.reset('single') +        self.config([self.packet, dict(self.packet, id='second-packet', issue=999)]) +        self.assertEqual(self.tick(calls=1)['packets'][1]['status'], 'queued') +    def test_ticket_accounting_identity_and_duplicate_worktree(self): +        (self.root / 'accounts').mkdir() +        ticket = dict(slots=2, pid=1000, start='123', claims=[], worktree=str(self.worktree)) +        queue.router.write_queue_tickets(self.root, {'token': ticket}) +        self.assertEqual(queue.router.occupancy(self.root), ([2, 0], [1, 0])) +        self.assertTrue(queue.worktree_busy(self.packet, self.root)) +        queue.atomic_write(self.root / 'watchdog/max-codex-primary', '2') +        with self.assertRaisesRegex(ValueError, 'capacity'): +            queue.router.reserve(self.root, 'primary', 1001, 0, True) +        self.host.return_value = ({1001: 1000}, {}) +        (self.root / 'watchdog/max-codex-primary').unlink() +        alias = self.base / 'alias' +        alias.symlink_to(self.worktree, target_is_directory=True) +        self.stack.enter_context(mock.patch.dict(os.environ, { +            'MIPSTARRE_DISPATCH_WORKTREE': str(alias)})) +        with self.assertRaisesRegex(ValueError, 'worktree reserved'): +            queue.router.reserve(self.root, 'primary', 1001, 0, True) +        os.environ['MIPSTARRE_QUEUE_TICKET'] = 'token' +        self.patch(queue.router.os, 'kill') +        self.assertEqual(queue.router.reserve(self.root, 'primary', 1001, 0, False), 'primary') +        self.assertEqual(qu