K : Type*} [Field K] [Fintype K]\\\\n    [DecidableEq K] [Fact p.Prime] [Algebra (ZMod p) K]\\\\n    (a : K) : Op K := fun i j => if i = j + a then 1 else 0\\\\n\\\\n/-- The phase observable in `lem:twisted-commutation`, blueprint\\\\n`ch11_qpbt_algebra.tex:553-597`, paper `04_preliminaries.tex:1056-1089`. -/\\\\nnoncomputable def primeTauPhase {p : ℕ} {K : Type*} [Field K] [Fintype K]\\\\n    [DecidableEq K] [Fact p.Prime] [Algebra (ZMod p) K]\\\\n    (b : K) : Op K := fun i j =>\\\\n  if i = j then ffChar (p := p) (F := K) (b * j) else 0\\\\n\\\\n/-- The multi-qudit observable in `lem:twisted-commutation`, with `false`\\\\nMIPStarRE/QPBT/State.lean\\\\nMIPStarRE/QPBT/Algebra/Pauli.lean\\\\n\\\",\\\"exit_code\\\":1,\\\"status\\\":\\\"failed\\\"}}\\nresults/telemetry/sessions/reviewer-pr184-20260905-04.jsonl-354-{\\\"type\\\":\\\"item.started\\\",\\\"item\\\":{\\\"id\\\":\\\"item_181\\\",\\\"type\\\":\\\"command_execution\\\",\\\"command\\\":\\\"/bin/bash -lc \\\\\\\"nl -ba blueprint/src/chapter/ch11_qpbt_algebra.tex | sed -n '730,835p'\\\\nnl -ba MIPStarRE/QPBT/Algebra/PauliTheorems.lean | sed -n '560,745p'\\\\\\\"\\\",\\\"aggregated_output\\\":\\\"\\\",\\\"exit_code\\\":null,\\\"status\\\":\\\"in_progress\\\"}}\\nresults/telemetry/sessions/reviewer-pr184-20260905-04.jsonl-355-{\\\"type\\\":\\\"item.completed\\\",\\\"item\\\":{\\\"id\\\":\\\"item_181\\\",\\\"type\\\":\\\"command_execution\\\",\\\"command\\\":\\\"/bin/bash -lc \\\\\\\"nl -ba blueprint/src/chapter/ch11_qpbt_algebra.tex | sed -n '730,835p'\\\\nnl -ba MIPStarRE/QPBT/Algebra/PauliTheorems.lean | sed -n '560,745p'\\\\\\\"\\\",\\\"aggregated_output\\\":\\\"   730\\\\t\\\\t$\\\\\\\\omega^{\\\\\\\\tr(a \\\\\\\\cdot b)}$: for $W = Z$ this is immediate from the\\\\n   731\\\\t\\\\tdefinition, and for $W = X$ it follows from the single-qudit computation\\\\n   732\\\\t\\\\t$\\\\\\\\tau^X(a)\\\\\\\\ket{e_X} = \\\\\\\\omega^{\\\\\\\\tr(ae)}\\\\\\\\ket{e_X}$, applied factor by factor.\\\\n   733\\\\t\\\\tExpanding $\\\\\\\\tau^W(a)$ in the orthonormal eigenbasis\\\\n   734\\\\t\\\\t$\\\\\\\\{\\\\\\\\ket{b_W}\\\\\\\\}_{b \\\\\\\\in \\\\\\\\F_q^n}$ gives the first display. For the inversion,\\\\n   735\\\\t\\\\tsubstitute the first display and exchange the order of summation; by\\\\n   736\\\\t\\\\tLemma~\\\\\\\\ref{lem:cancellation} applied with $V = \\\\\\\\F_q^n$ (so that\\\\n   737\\\\t\\\\t$V^\\\\\\\\perp = \\\\\\\\{0\\\\\\\\}$), the inner expectation vanishes unless $b' = b$, where\\\\n   738\\\\t\\\\tit equals $1$.\\\\n   739\\\\t\\\\\\\\end{proof}\\\\n   740\\\\t\\\\n   741\\\\tSince only admissible field sizes $q = 2^k$ arise in the Pauli basis test, the\\\\n   742\\\\tmaximally entangled state $\\\\\\\\ket{\\\\\\\\mathrm{EPR}_q}$ and the qudit Pauli\\\\n   743\\\\tprojectors are isomorphic to tensor products of qubit EPR states\\\\n   744\\\\t$\\\\\\\\ket{\\\\\\\\mathrm{EPR}_2}$ and qubit Pauli projectors. This is the content of the\\\\n   745\\\\tnext lemma, which is what allows the Pauli basis test to self-test Pauli\\\\n   746\\\\tobservables and maximally entangled states over \\\\\\\\emph{qubits}\\\\n   747\\\\t(Chapter~\\\\\\\\ref{chap:qpbt-test}).\\\\n   748\\\\t\\\\n   749\\\\t\\\\\\\\begin{lemma}[Qudit-to-qubit isomorphism]\\\\\\\\label{lem:pauli-binary}\\\\n   750\\\\t\\\\t\\\\\\\\lean{MIPStarRE.QPBT.qubitPauliProj, MIPStarRE.QPBT.exists_qubitIsometry}\\\\n   751\\\\t\\\\t\\\\\\\\leanok\\\\n   752\\\\t\\\\t\\\\\\\\uses{def:admissible-size, def:subfields-kappa, def:binary-representation,\\\\n   753\\\\t\\\\t\\\\tdef:generalized-pauli, def:EPR}\\\\n   754\\\\t\\\\tFor all admissible field sizes $q = 2^k$ and integers $L \\\\\\\\ge 0$, there\\\\n   755\\\\t\\\\texists an isomorphism $\\\\\\\\phi : (\\\\\\\\C^q)^{\\\\\\\\ot L} \\\\\\\\to (\\\\\\\\C^2)^{\\\\\\\\ot Lk}$ such that\\\\n   756\\\\t\\\\t\\\\\\\\begin{equation}\\\\\\\\label{eq:epr-q-to-epr-2}\\\\n   757\\\\t\\\\t\\\\t\\\\\\\\phi \\\\\\\\ot \\\\\\\\phi\\\\\\\\, \\\\\\\\ket{\\\\\\\\mathrm{EPR}_q}^{\\\\\\\\ot L}\\\\n   758\\\\t\\\\t\\\\t= \\\\\\\\ket{\\\\\\\\mathrm{EPR}_2}^{\\\\\\\\ot Lk}\\\\n   759\\\\t\\\\t\\\\\\\\end{equation}\\\\n   760\\\\t\\\\t(applying the natural identifications between\\\\n   761\\\\t\\\\t$(\\\\\\\\C^q)^{\\\\\\\\ot L} \\\\\\\\ot (\\\\\\\\C^q)^{\\\\\\\\ot L}$ and $(\\\\\\\\C^q \\\\\\\\ot \\\\\\\\C^q)^{\\\\\\\\ot L}$, and\\\\n   762\\\\t\\\\tbetween $(\\\\\\\\C^2)^{\\\\\\\\ot Lk} \\\\\\\\ot (\\\\\\\\C^2)^{\\\\\\\\ot Lk}$ and\\\\n   763\\\\t\\\\t$(\\\\\\\\C^2 \\\\\\\\ot \\\\\\\\C^2)^{\\\\\\\\ot Lk}$). Moreover, for all $W \\\\\\\\in \\\\\\\\{X, Z\\\\\\\\}$ and all\\\\n   764\\\\t\\\\t$u \\\\\\\\in \\\\\\\\F_q^L$,\\\\n   765\\\\t\\\\t\\\\\\\\begin{equation}\\\\\\\\label{eq:pauli-q-to-pauli-2}\\\\n   766\\\\t\\\\t\\\\t\\\\\\\\tau^W_u = \\\\\\\\phi^\\\\\\\\dagger\\\\\\\\,\\\\n   767\\\\t\\\\t\\\\t\\\\\\\\Bigl(\\\\\\\\bigotimes_{i=1}^L \\\\\\\\bigotimes_{j=1}^k\\\\n   768\\\\t\\\\t\\\\t\\\\\\\\sigma^W_{u_{ij}}\\\\\\\\Bigr)\\\\\\\\, \\\\\\\\phi\\\\\\\\;.\\\\n   769\\\\t\\\\t\\\\\\\\end{equation}\\\\n   770\\\\t\\\\tHere $(u_{ij})_{i,j}$ is the array of $\\\\\\\\F_2$ values with\\\\n   771\\\\t\\\\t$u_i = \\\\\\\\sum_j u_{ij} e_j$ for all $i \\\\\\\\in \\\\\\\\{1, \\\\\\\\dots, L\\\\\\\\}$, where\\\\n   772\\\\t\\\\t$\\\\\\\\{e_1, \\\\\\\\dots, e_k\\\\\\\\}$ is the fixed self-dual normal basis of $\\\\\\\\F_q$ over\\\\n   773\\\\t\\\\t$\\\\\\\\F_2$ of Definition~\\\\\\\\ref{def:binary-representation}; and for\\\\n   774\\\\t\\\\t$i \\\\\\\\in \\\\\\\\{1, \\\\\\\\dots, L\\\\\\\\}$ and $j \\\\\\\\in \\\\\\\\{1, \\\\\\\\dots, k\\\\\\\\}$ the $(i,j)$-th factor\\\\n   775\\\\t\\\\t$\\\\\\\\sigma^W_{u_{ij}}$ denotes the projector\\\\n   776\\\\t\\\\t$\\\\\\\\frac{1}{2}\\\\\\\\bigl(\\\\\\\\Id + (-1)^{u_{ij}} \\\\\\\\sigma^W(1)\\\\\\\\bigr)$ acting on the\\\\n   777\\\\t\\\\t$s$-th qubit, where $s = (i-1)k + j$.\\\\n   778\\\\t\\\\tWe index the product coordinates from zero: values $(i-1,j-1)$ correspond to\\\\n   779\\\\t\\\\tthe paper's pair $(i,j)$.  The corrected upper bound $j\\\\\\\\leq k$ is\\\\n   780\\\\t\\\\tdocumented in \\\\\\\\cite{gap:qpbt_pauli-binary-factor-index}.\\\\n   781\\\\t\\\\\\\\end{lemma}\\\\n   782\\\\t\\\\\\\\begin{proof}\\\\n   783\\\\t\\\\t\\\\\\\\leanok\\\\n   784\\\\t\\\\t\\\\\\\\uses{def:binary-representation, def:subfields-kappa, lem:downsize_field,\\\\n   785\\\\t\\\\t\\\\tdef:generalized-pauli, def:EPR, lem:pauli-observable-expansion}\\\\n   786\\\\t\\\\tThe formalized proof is a relabelling argument rather than a factorwise\\\\n   787\\\\t\\\\tconstruction. Let\\\\n   788\\\\t\\\\t$e : \\\\\\\\F_q^L \\\\\\\\to \\\\\\\\F_2^{L \\\\\\\\times k}$ be the bijection that expands each\\\\n   789\\\\t\\\\tcoordinate in the fixed self-dual normal basis\\\\n   790\\\\t\\\\t(Definition~\\\\\\\\ref{def:binary-representation}), so that $e(u)$ is exactly the\\\\n   791\\\\t\\\\tarray $(u_{ij})_{i,j}$ of the statement, and let $\\\\\\\\phi$ be the unitary that\\\\n   792\\\\t\\\\tpermutes the two computational bases along $e$, that is,\\\\n   793\\\\t\\\\t$\\\\\\\\phi \\\\\\\\ket{u} = \\\\\\\\ket{e(u)}$. Identity \\\\\\\\eqref{eq:epr-q-to-epr-2} holds for\\\\n   794\\\\t\\\\tany such relabelling: a bijection of orthonormal bases carries the maximally\\\\n   795\\\\t\\\\tentangled state of the source space to that of the target space. For\\\\n   796\\\\t\\\\t\\\\\\\\eqref{eq:pauli-q-to-pauli-2}, conjugation by $\\\\\\\\phi^\\\\\\\\dagger$ is exactly\\\\n   797\\\\t\\\\tthe reindexing of a matrix along $e$, so it suffices to compare matrix\\\\n   798\\\\t\\\\tentries. Both generalized Pauli observables are computed entrywise from\\\\n   799\\\\t\\\\tDefinition~\\\\\\\\ref{def:generalized-pauli}: $\\\\\\\\tau^W(a)$ is, for $W = X$, the\\\\n   800\\\\t\\\\tpermutation matrix of the translation $y \\\\\\\\mapsto y + a$, and, for $W = Z$,\\\\n   801\\\\t\\\\tthe diagonal matrix with entries $(-1)^{\\\\\\\\tr(a \\\\\\\\cdot y)}$. The relabelling\\\\n   802\\\\t\\\\t$e$ is additive, and item 2 of Lemma~\\\\\\\\ref{lem:downsize_field} gives\\\\n   803\\\\t\\\\t$\\\\\\\\tr(a \\\\\\\\cdot y) = e(a) \\\\\\\\cdot e(y)$ by self-duality of the basis; the two\\\\n   804\\\\t\\\\tentry formulas are therefore carried by the reindexing to the corresponding\\\\n   805\\\\t\\\\tformulas over $\\\\\\\\F_2$, so that $\\\\\\\\tau^W(a)$ becomes $\\\\\\\\tau^W(e(a))$ for both\\\\n   806\\\\t\\\\t$W$. Finally, the projectors are recovered from the observables by the\\\\n   807\\\\t\\\\tinversion identity \\\\\\\\eqref{eq:pauli-inversion-0} in its characteristic-two\\\\n   808\\\\t\\\\tform $\\\\\\\\tau^W_u = \\\\\\\\E_{\\\\\\\\ba} (-1)^{\\\\\\\\tr(\\\\\\\\ba \\\\\\\\cdot u)}\\\\\\\\, \\\\\\\\tau^W(\\\\\\\\ba)$, used\\\\n   809\\\\t\\\\tover $\\\\\\\\F_q^L$ on the left-hand side and over $\\\\\\\\F_2^{L \\\\\\\\times k}$ on the\\\\n   810\\\\t\\\\tright; averaging the entrywise comparison\\\\n   811\\\\t\\\\tover $\\\\\\\\ba$ carries $\\\\\\\\tau^W_u$ to the qubit projector at the label\\\\n   812\\\\t\\\\t$e(u) = \\\\\\\\kappa(u)$, which is \\\\\\\\eqref{eq:pauli-q-to-pauli-2}. Only this\\\\n   813\\\\t\\\\tcharacteristic-two specialization of\\\\n   814\\\\t\\\\tLemma~\\\\\\\\ref{lem:pauli-observable-expansion} is formalized; its\\\\n   815\\\\t\\\\tgeneral-prime expansion and inversion have no Lean declaration, as\\\\n   816\\\\t\\\\trecorded in \\\\\\\\cite{gap:qpbt_characteristic-two-pauli-scope}. The formalized\\\\n   817\\\\t\\\\targument uses neither the qudit-by-qudit isometry $\\\\\\\\theta$ of the source\\\\n   818\\\\t\\\\tproof nor the product and twisted-commutation relations of\\\\n   819\\\\t\\\\tLemma~\\\\\\\\ref{lem:twisted-commutation}.\\\\n   820\\\\t\\\\\\\\end{proof}\\\\n   821\\\\t\\\\n   822\\\\t\\\\\\\\begin{remark}\\\\\\\\label{rem:pauli-binary-source}\\\\n   823\\\\t\\\\tIn the source statement of Lemma~\\\\\\\\ref{lem:pauli-binary} in\\\\n   824\\\\t\\\\t\\\\\\\\cite{Ji2020MIPStar}, the index range of the qubit factor is printed as\\\\n   825\\\\t\\\\t$j \\\\\\\\in \\\\\\\\{1, \\\\\\\\dots, q\\\\\\\\}$; the intended range, used above, is\\\\n   826\\\\t\\\\t$j \\\\\\\\in \\\\\\\\{1, \\\\\\\\dots, k\\\\\\\\}$, as the $i$-th qudit is mapped to $k$ qubits. The\\\\n   827\\\\t\\\\tsource also quantifies over arbitrary integers $L$; the statement above\\\\n   828\\\\t\\\\ttakes $L$ to be a natural number, including zero, and uses the usual\\\\n   829\\\\t\\\\tempty-product convention for the tensor powers when $L=0$.  The index\\\\n   830\\\\t\\\\tcorrection is documented in \\\\\\\\cite{gap:qpbt_pauli-binary-factor-index}.\\\\n   831\\\\t\\\\\\\\end{remark}\\\\n   560\\\\t    Matrix.reindex_apply, Matrix.submatrix_apply]\\\\n   561\\\\t  rw [Fintype.sum_eq_single (e y)]\\\\n   562\\\\t  · rw [Fintype.sum_eq_single (e x)]\\\\n   563\\\\t    · simp [piLpCongrLeft_matrix_apply]\\\\n   564\\\\t    · intro j hj\\\\n   565\\\\t      have hxj : x ≠ e.symm j := by\\\\n   566\\\\t        intro h\\\\n   567\\\\t        apply hj\\\\n   568\\\\t        simp [h]\\\\n   569\\\\t      simp [piLpCongrLeft_matrix_apply, hxj]\\\\n   570\\\\t  · intro i hi\\\\n   571\\\\t    have hyi : y ≠ e.symm i := by\\\\n   572\\\\t      intro h\\\\n   573\\\\t      apply hi\\\\n   574\\\\t      simp [h]\\\\n   575\\\\t    simp [piLpCongrLeft_matrix_apply, hyi]\\\\n   576\\\\t\\\\n   577\\\\t/-- The label equivalence obtained by expanding each field element in the fixed\\\\n   578\\\\tself-dual binary basis. -/\\\\n   579\\\\tprivate noncomputable def quditQubitLabelEquiv {q : ℕ}\\\\n   580\\\\t    (F : FixedFieldModel q) (L : ℕ) :\\\\n   581\\\\t    (Fin L → F.K) ≃ (Fin L × Fin F.basisDim → ZMod 2) :=\\\\n   582\\\\t  (Equiv.piCongrRight (fun _ : Fin L => F.binaryCoordinates.toEquiv)).trans\\\\n   583\\\\t    (Equiv.curry (Fin L) (Fin F.basisDim) (ZMod 2)).symm\\\\n   584\\\\t\\\\n   585\\\\t/-- The label equivalence is the uncurried form of `kappaVec`. -/\\\\n   586\\\\tprivate theorem quditQubitLabelEquiv_eq_kappaVec {q : ℕ}\\\\n   587\\\\t    (F : FixedFieldModel q) (L : ℕ) (u : Fin L → F.K) :\\\\n   588\\\\t    quditQubitLabelEquiv F L u = kappaVec F u := by\\\\n   589\\\\t  rfl\\\\n   590\\\\t\\\\n   591\\\\t/-- Self-duality identifies the field trace pairing with the binary coordinate\\\\n   592\\\\tpairing after relabeling. -/\\\\n   593\\\\tprivate theorem binTrace_dotProduct_eq_quditQubitLabelEquiv\\\\n   594\\\\t    {q : ℕ} (F : FixedFieldModel q) (L : ℕ) (a u : Fin L → F.K) :\\\\n   595\\\\t    binTrace F.K (dotProduct a u) =\\\\n   596\\\\t      binTrace (ZMod 2)\\\\n   597\\\\t        (dotProduct (quditQubitLabelEquiv F L a) (kappaVec F u)) := by\\\\n   598\\\\t  simp only [dotProduct, map_sum, binTrace_mul_eq_dotProduct F,\\\\n   599\\\\t    Algebra.trace_self_apply, Fintype.sum_prod_type, quditQubitLabelEquiv,\\\\n   600\\\\t    Equiv.trans_apply, Equiv.curry_symm_apply, kappaVec, basisCoordVec]\\\\n   601\\\\t  rfl\\\\n   602\\\\t\\\\n   603\\\\t/-- The coordinate label equivalence preserves addition. -/\\\\n   604\\\\tprivate theorem quditQubitLabelEquiv_add {q : ℕ}\\\\n   605\\\\t    (F : FixedFieldModel q) (L : ℕ) (a b : Fin L → F.K) :\\\\n   606\\\\t    quditQubitLabelEquiv F L (a + b) =\\\\n   607\\\\t      quditQubitLabelEquiv F L a + quditQubitLabelEquiv F L b := by\\\\n   608\\\\t  ext p\\\\n   609\\\\t  rcases p with ⟨i, j⟩\\\\n   610\\\\t  change F.binaryCoordinates (a i + b i) j =\\\\n   611\\\\t    F.binaryCoordinates (a i) j + F.binaryCoordinates (b i) j\\\\n   612\\\\t  simp\\\\n   613\\\\t\\\\n   614\\\\t/-- A shift observable is the permutation matrix for addition by its label. -/\\\\n   615\\\\tprivate theorem tauObservable_X_apply\\\\n   616\\\\t    {K ι : Type*} [Field K] [DecidableEq K]\\\\n   617\\\\t    [Algebra (ZMod 2) K] [Fintype ι] [DecidableEq ι]\\\\n   618\\\\t    (a x y : ι → K) :\\\\n   619\\\\t    tauObservable .X a x y = if x = y + a then 1 else 0 := by\\\\n   620\\\\t  change (∏ i : ι, if x i = y i + a i then 1 else 0) = _\\\\n   621\\\\t  rw [Fintype.prod_boole]\\\\n   622\\\\t  have hsupport : (∀ i, x i = y i + a i) ↔ x = y + a := by\\\\n   623\\\\t    simpa only [Pi.add_apply] using\\\\n   624\\\\t      (funext_iff (f := x) (g := y + a)).symm\\\\n   625\\\\t  simp only [hsupport]\\\\n   626\\\\t\\\\n   627\\\\t/-- A phase observable is diagonal, with its phase given by the trace pairing. -/\\\\n   628\\\\tprivate theorem tauObservable_Z_apply\\\\n   629\\\\t    {K ι : Type*} [Field K] [DecidableEq K]\\\\n   630\\\\t    [Algebra (ZMod 2) K] [Fintype ι] [DecidableEq ι]\\\\n   631\\\\t    (a x y : ι → K) :\\\\n   632\\\\t    tauObservable .Z a x y =\\\\n   633\\\\t      if x = y then phaseSign (binTrace K (dotProduct a y)) else 0 := by\\\\n   634\\\\t  change\\\\n   635\\\\t    (∏ i : ι,\\\\n   636\\\\t      if x i = y i then phaseSign (binTrace K (a i * y i)) else 0) = _\\\\n   637\\\\t  rw [Fintype.prod_ite_zero, prod_phaseSign_binTrace_dotProduct]\\\\n   638\\\\t  have hsupport : (∀ i, x i = y i) ↔ x = y :=\\\\n   639\\\\t    (funext_iff (f := x) (g := y)).symm\\\\n   640\\\\t  simp only [hsupport]\\\\n   641\\\\t\\\\n   642\\\\t/-- Binary-coordinate relabeling transports both generalized Pauli observables. -/\\\\n   643\\\\tprivate theorem tauObservable_reindex_quditQubitLabelEquiv\\\\n   644\\\\t    {q : ℕ} (F : FixedFieldModel q) (L : ℕ)\\\\n   645\\\\t    (W : PauliKind) (a : Fin L → F.K) :\\\\n   646\\\\t    tauObservable W a =\\\\n   647\\\\t      Matrix.reindex (quditQubitLabelEquiv F L).symm\\\\n   648\\\\t        (quditQubitLabelEquiv F L).symm\\\\n   649\\\\t        (tauObservable W (quditQubitLabelEquiv F L a)) := by\\\\n   650\\\\t  classical\\\\n   651\\\\t  ext x y\\\\n   652\\\\t  simp only [Matrix.reindex_apply, Matrix.submatrix_apply, Equiv.symm_symm]\\\\n   653\\\\t  cases W with\\\\n   654\\\\t  | X =>\\\\n   655\\\\t      rw [tauObservable_X_apply, tauObservable_X_apply]\\\\n   656\\\\t      have hadd := quditQubitLabelEquiv_add F L y a\\\\n   657\\\\t      rw [← hadd]\\\\n   658\\\\t      by_cases hshift : x = y + a\\\\n   659\\\\t      · rw [if_pos hshift, if_pos]\\\\n   660\\\\t        exact congrArg (quditQubitLabelEquiv F L) hshift\\\\n   661\\\\t      · rw [if_neg hshift, if_neg]\\\\n   662\\\\t        exact fun h => hshift ((quditQubitLabelEquiv F L).injective h)\\\\n   663\\\\t  | Z =>\\\\n   664\\\\t      rw [tauObservable_Z_apply, tauObservable_Z_apply]\\\\n   665\\\\t      by_cases hxy : x = y\\\\n   666\\\\t      · subst y\\\\n   667\\\\t        rw [if_pos rfl, if_pos rfl,\\\\n   668\\\\t          binTrace_dotProduct_eq_quditQubitLabelEquiv,\\\\n   669\\\\t          quditQubitLabelEquiv_eq_kappaVec F L a,\\\\n   670\\\\t          quditQubitLabelEquiv_eq_kappaVec F L x]\\\\n   671\\\\t      · have hlabels : quditQubitLabelEquiv F L x ≠\\\\n   672\\\\t            quditQubitLabelEquiv F L y := fun h =>\\\\n   673\\\\t          hxy ((quditQubitLabelEquiv F L).injective h)\\\\n   674\\\\t        rw [if_neg hxy, if_neg hlabels]\\\\n   675\\\\t\\\\n   676\\\\t/-- Fourier inversion transports the Pauli projectors along the binary label\\\\n   677\\\\tequivalence. -/\\\\n   678\\\\tprivate theorem pauliProj_reindex_quditQubitLabelEquiv\\\\n   679\\\\t    {q : ℕ} (F : FixedFieldModel q) (L : ℕ)\\\\n   680\\\\t    (W : PauliKind) (u : Fin L → F.K) :\\\\n   681\\\\t    pauliProj W u =\\\\n   682\\\\t      Matrix.reindex (quditQubitLabelEquiv F L).symm\\\\n   683\\\\t        (quditQubitLabelEquiv F L).symm\\\\n   684\\\\t        (pauliProj W (kappaVec F u)) := by\\\\n   685\\\\t  classical\\\\n   686\\\\t  rw [pauliProj_eq_avg_tauObservable, pauliProj_eq_avg_tauObservable]\\\\n   687\\\\t  ext x y\\\\n   688\\\\t  simp only [Matrix.smul_apply, Matrix.sum_apply, smul_eq_mul,\\\\n   689\\\\t    Matrix.reindex_apply, Matrix.submatrix_apply, Equiv.symm_symm]\\\\n   690\\\\t  rw [Fintype.card_congr (quditQubitLabelEquiv F L)]\\\\n   691\\\\t  congr 1\\\\n   692\\\\t  apply Fintype.sum_equiv (quditQubitLabelEquiv F L)\\\\n   693\\\\t  intro a\\\\n   694\\\\t  have hphas